/// Bangun domain models: alarms with schedule rules, challenge config,
/// ringtone sources, and wake statistics.
library;

import 'dart:math' as math;

import 'package:collection/collection.dart';

import '../core/format.dart';

/// How often the alarm repeats.
enum RepeatMode { once, daily, weekly }

/// Which gate blocks the "stop" button.
enum ChallengeKind { math, scan, mix }

/// Where the ringing sound comes from.
enum ToneKind { builtin, file, spotify }

/// Built-in tones generated by `tools/gen_sounds.dart`.
enum BuiltInTone {
  morningBricks('morning_bricks.wav', 'Morning bricks', '🔔'),
  twinChime('twin_chime.wav', 'Twin chime', '🔊'),
  sirenRush('siren_rush.wav', 'Siren rush', '🚨'),
  digitalChirp('digital_chirp.wav', 'Digital chirp', '📟');

  const BuiltInTone(this.file, this.title, this.emoji);

  final String file;
  final String title;
  final String emoji;

  String get assetPath => 'assets/sounds/$file';
}

